        SelectedUpgradeToBuy = getgenv().SelectedUpgradeToBuy or "__ALL__",
        UpgradeBuyDelay = tonumber(getgenv().UpgradeBuyDelay) or 0.8,
    }

    local ok = pcall(function()
        writefile(ConfigPath, HttpService:JSONEncode(data))
